/** Leaves one compound path ready for stroke/fill; original contour winding keeps letter holes open. */
export function traceComboPraiseLettering(ctx: CanvasRenderingContext2D, tier: ComboPraiseLetteringTier): void {
  const lettering: ComboPraiseLettering = COMBO_PRAISE_LETTERING[tier];
  ctx.beginPath();
  for (const command of lettering.commands) {
    switch (command[0]) {
      case "M": ctx.moveTo(command[1], command[2]); break;
      case "L": ctx.lineTo(command[1], command[2]); break;
      case "Q": ctx.quadraticCurveTo(command[1], command[2], command[3], command[4]); break;
      case "C": ctx.bezierCurveTo(command[1], command[2], command[3], command[4], command[5], command[6]); break;
      case "Z": ctx.closePath(); break;
    }
  }
}
